mapper.select:
select app.App_Name as appName, app.App_Code as appCode, app.App_Type as appType, te.Te_Name as teName, te.Te_Code as teCode, te.Te_Type as teType, te.Te_Charge_Type as teChargeType, te.Te_Expiration_Time as teExpirationTime, mn.* from SYS_TenantApplication mn left join SYS_Tenant te on te.Te_Id=mn.Te_Id left join SYS_Application app on app.App_Id=mn.App_Id
and te.Te_Type=#{params.teType}
and app.App_Type=#{params.appType}
and te.Te_Charge_Type=#{params.teChargeType}
and INSTR(app.App_Name,#{params.appName})
and INSTR(app.App_Code,#{params.appCode})
and INSTR(te.Te_Name,#{params.teName})
and INSTR(te.Te_Code,#{params.teCode})
order by mn.${params.sortFiled} ${params.sortType}
order by te.Create_Time DESC
